mapper.select:
SELECT EXISTS (
    SELECT 1 FROM tb_users u WHERE #{purpose} = 'PROFILE' AND u.profile_image_id = #{fileId}
    UNION ALL
    SELECT 1 FROM tb_courses c WHERE #{purpose} = 'COURSE_THUMBNAIL' AND c.thumbnail_file_id = #{fileId}
    UNION ALL
    SELECT 1 FROM tb_course_attachments a WHERE #{purpose} = 'COURSE_ATTACHMENT' AND a.file_id = #{fileId}
    UNION ALL
    SELECT 1 FROM tb_institutions i WHERE #{purpose} = 'INSTITUTION_LOGO' AND i.logo_file_id = #{fileId}
    UNION ALL
    SELECT 1 FROM tb_notice_attachments a WHERE #{purpose} = 'NOTICE_ATTACHMENT' AND a.file_id = #{fileId}
    UNION ALL
    SELECT 1 FROM tb_banners b WHERE #{purpose} = 'BANNER'
       AND (b.pc_image_file_id = #{fileId} OR b.mobile_image_file_id = #{fileId})
    UNION ALL
    SELECT 1 FROM tb_badge_definitions d WHERE #{purpose} = 'BADGE_IMAGE' AND (d.image_file_id = #{fileId}
       OR d.rule_params -> 'levels' @> )
)

SELECT EXISTS (
    SELECT 1 FROM tb_courses c WHERE #{purpose} = 'COURSE_THUMBNAIL'
       AND c.thumbnail_file_id = #{fileId} AND c.institution_id = #{institutionId}
    UNION ALL
    SELECT 1 FROM tb_courses c JOIN tb_course_attachments a ON a.course_id = c.id
     WHERE #{purpose} = 'COURSE_ATTACHMENT' AND a.file_id = #{fileId}
       AND c.institution_id = #{institutionId}
    UNION ALL
    SELECT 1 FROM tb_institutions i WHERE #{purpose} = 'INSTITUTION_LOGO'
       AND i.logo_file_id = #{fileId} AND i.id = #{institutionId}
)
